          "speaker": "La Rose",
          "fr": {
            "text": "Le soir vous me mettrez sous globe. Il fait froid ici.",
            "audio_mp3": "books/petit-prince/kids_audio/fr_bubble_p08.mp3",
            "audio_ogg": "books/petit-prince/kids_audio/fr_bubble_p08.ogg"
          },
          "it": {
            "text": "La sera mi metterete sotto la campana. Qui fa freddo.",
            "audio_mp3": "books/petit-prince/kids_audio/it_bubble_p08.mp3",
            "audio_ogg": "books/petit-prince/kids_audio/it_bubble_p08.ogg"
          },
